(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.02-t*0.15)*12;
  const w1y = Math.cos(y*0.018-t*0.22)*18 + Math.sin(x*0.022+t*0.18)*10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025+t*0.3)*8 + Math.cos(sy*0.03-t*0.25)*6;
  const w2y = Math.cos(sy*0.028-t*0.28)*7 + Math.sin(sx*0.02+t*0.32)*5;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.9],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.2],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.7],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,1.0],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65)*40,0.14,2.1,0.85],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+1)*50,0.055,1.8,1.15],
    [200+Math.sin(t*0.7+4)*90,220+Math.cos(t*0.3+3)*60,0.11,2.4,0.95]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.8+3)*w*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,cross=cS/n;
  const bg1=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2;
  const bg2=Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2;
  const bg3=Math.sin(fx*0.08+fy*0.06-t*1.8)*Math.cos(fx*0.05-fy*0.09+t*1.4)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2);
  const ang=Math.atan2(fy-cy,fx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.03+ang*5-t*0.9)*Math.cos(dist*0.07-ang*2+t*1.6)*0.2;
  const rd=act-inh*0.7+cross*0.3+bg*0.25+sp1+sp2;
  const reaction=Math.tanh(rd*2.2);
  const c1=Math.sin(fx*0.15)*Math.sin(fy*0.15);
  const c2=Math.sin((fx+fy)*0.1+t)*0.5;
  const c3=Math.sin(fx*0.22-fy*0.18+t*0.7)*0.3;
  const cell=Math.tanh((c1+c2+c3)*1.5)*0.3;
  const micro=Math.sin(fx*0.4+fy*0.35+t*3)*Math.sin(fx*0.3-fy*0.45-t*2.5)*0.08;
  const pulse=1.0+Math.sin(t*0.4)*0.08+Math.sin(t*0.7+1)*0.05;
  const blend=reaction*0.65+cell*0.25+micro;
  const v=(blend*pulse)*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,95,120],[25,155,130],[120,185,95],[220,195,60],[235,140,55],[220,80,65],[180,45,75],[120,25,65],[55,15,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.75?1.12:1.0;
  const glow=Math.max(0,reaction*0.3)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*255)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*200)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*150)|0)
  ];
}
